import React, { useState } from "react";
import { AgGridReact } from "ag-grid-react";
import "ag-grid-community/styles/ag-grid.css";
import "ag-grid-community/styles/ag-theme-alpine.css";

interface ListProps {
  users: {
    id: string;
    username: string;
    email: string;
    gender: string;
    age: number;
    first_name: string;
    last_name: string;
    phone_number: string;
    created_at: string;
    is_active: boolean;
    address: string;
    city: string;
    state: string;
    zip_code: string;
    country: string;
    [key: string]: any; // Allow any additional user properties
  }[];
  columnsConfig: {
    headerName: string;
    field: string;
    sortable?: boolean;
    filter?: boolean;
    resizable?: boolean;
  }[];
}

const List: React.FC<ListProps> = ({ users, columnsConfig }) => {
  const [selectedUser, setSelectedUser] = useState<any | null>(null);

  // Default column definition for grid
  const defaultColDef = {
    sortable: true,
    filter: true,
    resizable: true,
  };

  const handleRowClick = (event: any) => {
    setSelectedUser(event.data);
  };

  const handleCloseModal = () => {
    setSelectedUser(null);
  };

  return (
    <div className="p-4">
      <h1 className="text-xl font-semibold mb-4">User List</h1>
      <div className="ag-theme-alpine" style={{ height: 600, width: "100%" }}>
        <AgGridReact
          rowData={users}
          columnDefs={columnsConfig}
          defaultColDef={defaultColDef}
          onRowClicked={handleRowClick}
          pagination={true}
          paginationPageSize={10}
        />
      </div>

      {/* Modal for user details */}
      {selectedUser && (
        <div className="fixed inset-0 flex items-center justify-center z-50 bg-black bg-opacity-50">
          <div className="bg-white rounded-lg w-11/12 md:w-2/3 lg:w-1/2 p-6 shadow-lg max-h-screen overflow-y-auto">
            <div className="flex justify-between items-center mb-4">
              <h3 className="text-lg font-semibold">{selectedUser.first_name} {selectedUser.last_name}</h3>
              <button
                onClick={handleCloseModal}
                className="text-sm font-medium text-gray-600 hover:text-gray-800"
              >
                Close
              </button>
            </div>

            <div className="overflow-x-auto">
              <table className="min-w-full table-auto">
                <thead>
                  <tr className="bg-gray-100">
                    <th className="px-4 py-2 text-left text-sm font-medium text-gray-700">Field</th>
                    <th className="px-4 py-2 text-left text-sm font-medium text-gray-700">Value</th>
                  </tr>
                </thead>
                <tbody>
                  {Object.entries(selectedUser).map(([key, value]) => (
                    <tr key={key} className="border-b">
                      <td className="px-4 py-2 text-sm font-medium text-gray-600 capitalize">
                        {key.replace(/_/g, " ")}
                      </td>
                      <td className="px-4 py-2 text-sm text-gray-900">
                        {typeof value === "boolean" ? (value ? "Yes" : "No") : value}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default List;
